// no Functor in Go: one hand-written helper per container kind
func Map[T, U any](s []T, f func(T) U) []U {
    out := make([]U, len(s))
    for i, v := range s {
        out[i] = f(v)
    }
    return out
}

type Opt[T any] struct{ ok bool; v T }

func (o Opt[T]) Map(f func(T) T) Opt[T] {   // the context's own instance
    if !o.ok { return o }
    return Opt[T]{true, f(o.v)}
}
